// 选择素材和产品
const materialData = $('查询素材库').first().json;
const productData = $('查询产品库').first().json;

const materials = materialData.results || [];
const products = productData.results || [];

if (materials.length === 0) {
  throw new Error('素材库为空，请先采集素材');
}

if (products.length === 0) {
  throw new Error('产品库为空，请先添加产品');
}

// 随机选择1条素材
const selectedMaterial = materials[Math.floor(Math.random() * materials.length)];

// 随机选择1-2款产品
const productCount = Math.random() > 0.5 ? 2 : 1;
const selectedProducts = [];
const usedIndices = new Set();

while (selectedProducts.length < productCount && selectedProducts.length < products.length) {
  const index = Math.floor(Math.random() * products.length);
  if (!usedIndices.has(index)) {
    usedIndices.add(index);
    selectedProducts.push(products[index]);
  }
}

// 提取素材信息
const materialTitle = selectedMaterial.properties['标题']?.title?.[0]?.text?.content || '无标题';
const materialSummary = selectedMaterial.properties['原文摘要']?.rich_text?.[0]?.text?.content || '';
const materialContent = selectedMaterial.properties['详细内容']?.rich_text?.[0]?.text?.content || materialSummary;
const materialAngles = selectedMaterial.properties['创作角度']?.rich_text?.[0]?.text?.content || '';
const materialTopics = selectedMaterial.properties['话题分类']?.multi_select?.map(t => t.name).join(', ') || '';
const materialMBTI = selectedMaterial.properties['MBTI相关']?.multi_select?.map(t => t.name).join(', ') || '';

// 提取产品信息
const productInfos = selectedProducts.map(p => {
  return {
    name: p.properties['产品名称']?.title?.[0]?.text?.content || '未命名',
    mbtiType: p.properties['MBTI类型']?.select?.name || '',
    personality: p.properties['人格特质']?.rich_text?.[0]?.text?.content || '',
    sellPoint: p.properties['核心卖点']?.rich_text?.[0]?.text?.content || '',
    scene: p.properties['适合场景']?.rich_text?.[0]?.text?.content || '',
    taste: p.properties['口味描述']?.rich_text?.[0]?.text?.content || ''
  };
});

return [{
  json: {
    material: {
      title: materialTitle,
      summary: materialSummary,
      content: materialContent,
      angles: materialAngles,
      topics: materialTopics,
      mbti: materialMBTI
    },
    products: productInfos,
    timestamp: new Date().toISOString()
  }
}];

