// 整合小红书内容
const selectedData = $('选择素材和产品').first().json;
const titleResponse = $('AI生成小红书标题').first().json;
const contentResponse = $('AI生成小红书正文').first().json;

// 解析AI返回的JSON
let title = '默认标题';
let content = '';
let tags = [];
let images = [];

try {
  const titleData = titleResponse.choices?.[0]?.message?.content || '{}';
  const titleMatch = titleData.match(/\{[\s\S]*\}/);
  if (titleMatch) {
    const titleJson = JSON.parse(titleMatch[0]);
    title = titleJson.title || title;
  }
} catch (e) {
  title = selectedData.material.title + ' | ' + selectedData.products[0].name;
}

try {
  const contentData = contentResponse.choices?.[0]?.message?.content || '{}';
  const contentMatch = contentData.match(/\{[\s\S]*\}/);
  if (contentMatch) {
    const contentJson = JSON.parse(contentMatch[0]);
    content = contentJson.content || '';
    tags = contentJson.tags || [];
    images = contentJson.images || [];
  }
} catch (e) {
  content = '内容生成失败，请手动编辑';
}

const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    title: title,
    content: content,
    tags: tags,
    images: images,
    platform: '小红书',
    contentType: '图文笔记',
    materialSource: selectedData.material.title,
    relatedProducts: selectedData.products.map(p => p.name).join('、'),
    status: '待审核',
    createdAt: today
  }
}];

// 整合公众号内容
const selectedData = $('选择素材和产品').first().json;
const titleResponse = $('AI生成公众号标题').first().json;
const contentResponse = $('AI生成公众号正文').first().json;

// 解析AI返回的JSON
let title = '默认标题';
let fullContent = '';

try {
  const titleData = titleResponse.choices?.[0]?.message?.content || '{}';
  const titleMatch = titleData.match(/\{[\s\S]*\}/);
  if (titleMatch) {
    const titleJson = JSON.parse(titleMatch[0]);
    title = titleJson.title || title;
  }
} catch (e) {
  title = selectedData.material.title + ' | ' + selectedData.products[0].name;
}

try {
  const contentData = contentResponse.choices?.[0]?.message?.content || '{}';
  const contentMatch = contentData.match(/\{[\s\S]*\}/);
  if (contentMatch) {
    const contentJson = JSON.parse(contentMatch[0]);

    // 组装完整文章
    fullContent = contentJson.intro + '\n\n';

    if (contentJson.sections && Array.isArray(contentJson.sections)) {
      contentJson.sections.forEach(section => {
        fullContent += `## ${section.subtitle}\n\n${section.content}\n\n`;
      });
    }

    fullContent += `## 产品推荐\n\n${contentJson.productIntro}\n\n`;
    fullContent += contentJson.ending;
  }
} catch (e) {
  fullContent = '内容生成失败，请手动编辑';
}

const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    title: title,
    content: fullContent,
    platform: '公众号',
    contentType: '深度文章',
    materialSource: selectedData.material.title,
    relatedProducts: selectedData.products.map(p => p.name).join('、'),
    status: '待审核',
    createdAt: today
  }
}];

// 构建Notion请求体（小红书）
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_CREATION_DATABASE_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title } }] },
    '平台': { select: { name: d.platform } },
    '内容类型': { select: { name: d.contentType } },
    '正文': { rich_text: [{ text: { content: d.content.substring(0, 2000) } }] },
    '标签': { multi_select: d.tags.slice(0, 5).map(tag => ({ name: tag })) },
    '配图建议': { rich_text: [{ text: { content: d.images.join('\n').substring(0, 500) } }] },
    '素材来源': { rich_text: [{ text: { content: d.materialSource } }] },
    '关联产品': { rich_text: [{ text: { content: d.relatedProducts } }] },
    '状态': { select: { name: d.status } },
    '创建时间': { date: { start: d.createdAt } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 构建Notion请求体（公众号）
const d = $json;
const body = {
  parent: { database_id: process.env.NOTION_CREATION_DATABASE_ID },
  properties: {
    '标题': { title: [{ text: { content: d.title } }] },
    '平台': { select: { name: d.platform } },
    '内容类型': { select: { name: d.contentType } },
    '正文': { rich_text: [{ text: { content: d.content.substring(0, 2000) } }] },
    '素材来源': { rich_text: [{ text: { content: d.materialSource } }] },
    '关联产品': { rich_text: [{ text: { content: d.relatedProducts } }] },
    '状态': { select: { name: d.status } },
    '创建时间': { date: { start: d.createdAt } }
  }
};
return [{ json: { notionBody: JSON.stringify(body), originalData: d } }];

// 生成执行摘要
const items = $input.first().json.data || [];
const xhsSuccess = items.filter(item => item.originalData?.platform === '小红书' && item.id).length;
const wechatSuccess = items.filter(item => item.originalData?.platform === '公众号' && item.id).length;

const selectedData = $('选择素材和产品').first().json;

const summary = `MBTI内容创作报告
========================
执行时间: ${new Date().toLocaleString('zh-CN')}

【素材】
- ${selectedData.material.title}
- 话题: ${selectedData.material.topics}

【产品】
${selectedData.products.map(p => `- ${p.name} (${p.mbtiType})`).join('\n')}

【创作结果】
- 小红书: ${xhsSuccess > 0 ? '✓ 成功' : '✗ 失败'}
- 公众号: ${wechatSuccess > 0 ? '✓ 成功' : '✗ 失败'}

【下一步】
1. 在Notion创作库中审核内容
2. 修改优化后标记为

3. 使用发布工作流发布到平台`;

return [{
  json: {
    report: summary,
    xhsSuccess,
    wechatSuccess,
    totalSuccess: xhsSuccess + wechatSuccess,
    timestamp: new Date().toISOString()
  }
}];
